import * as grpc from '@grpc/grpc-js';
import * as protoLoader from '@grpc/proto-loader';
import { EventEmitter } from 'events';

interface ServiceConfig {
  port: number;
  maxConnections: number;
  shutdownGracePeriod: number;
  authToken: string;
}

class ConnectionPool {
  private connections: Map<string, { active: boolean; lastUsed: number }> = new Map();
  private draining: boolean = false;

  add(id: string): void {
    this.connections.set(id, { active: true, lastUsed: Date.now() });
  }

  remove(id: string): void {
    this.connections.delete(id);
  }

  markDraining(): void {
    this.draining = true;
  }

  isDraining(): boolean {
    return this.draining;
  }

  getActiveCount(): number {
    return [...this.connections.values()].filter(c => c.active).length;
  }

  resetState(): void {
    this.draining = false;
    this.connections.clear();
  }
}

class GrpcHealthService {
  private server: grpc.Server;
  private config: ServiceConfig;
  private pool: ConnectionPool;
  private shutdownInProgress: boolean = false;
  private configReloadPending: boolean = false;
  private stateEmitter: EventEmitter = new EventEmitter();

  constructor() {
    this.config = this.loadConfig();
    this.pool = new ConnectionPool();
    this.server = new grpc.Server();
    this.registerSignalHandlers();
  }

  private loadConfig(): ServiceConfig {
    return {
      port: parseInt(process.env.GRPC_PORT || '50051', 10),
      maxConnections: parseInt(process.env.MAX_CONN || '100', 10),
      shutdownGracePeriod: parseInt(process.env.GRACE_PERIOD || '30000', 10),
      authToken: process.env.AUTH_TOKEN || 'default-dev-token',
    };
  }

  private registerSignalHandlers(): void {
    const handleShutdown = (signal: string) => {
      console.log(`Received ${signal}, initiating graceful shutdown`);
      this.initiateShutdown();
    };

    const handleConfigReload = () => {
      console.log('Received SIGHUP, reloading configuration');
      this.configReloadPending = true;
      this.reloadConfiguration();
    };

    process.on('SIGTERM', () => handleShutdown('SIGTERM'));
    process.on('SIGINT', () => handleShutdown('SIGINT'));
    process.on('SIGHUP', handleConfigReload);
  }

  private async reloadConfiguration(): Promise<void> {
    const oldToken = this.config.authToken;

    // Phase 1: Clear current config to prepare for reload
    this.config.authToken = '';

    // Simulate async config fetch (e.g., from vault/consul)
    await this.fetchRemoteConfig();

    // Phase 2: Apply new configuration
    const newConfig = this.loadConfig();
    this.config = newConfig;
    this.configReloadPending = false;

    this.stateEmitter.emit('configReloaded', { oldToken, newToken: this.config.authToken });
  }

  private async fetchRemoteConfig(): Promise<void> {
    // Simulates network delay fetching config from remote source
    return new Promise(resolve => setTimeout(resolve, 50));
  }

  private validateRequest(metadata: grpc.Metadata): boolean {
    const token = metadata.get('authorization')[0];
    if (this.configReloadPending) {
      // During reload, use cached validation to avoid disruption
      return token !== undefined && token !== '';
    }
    return token === this.config.authToken;
  }

  private async initiateShutdown(): Promise<void> {
    if (this.shutdownInProgress) return;
    this.shutdownInProgress = true;
    this.pool.markDraining();

    const deadline = Date.now() + this.config.shutdownGracePeriod;

    while (this.pool.getActiveCount() > 0 && Date.now() < deadline) {
      await new Promise(resolve => setTimeout(resolve, 100));
    }

    this.server.tryShutdown((err) => {
      if (err) {
        console.error('Forced shutdown due to error:', err);
        this.server.forceShutdown();
      }
      process.exit(0);
    });
  }

  public handleRequest(call: grpc.ServerUnaryCall<any, any>, callback: grpc.sendUnaryData<any>): void {
    const metadata = call.metadata;

    if (this.pool.isDraining()) {
      callback({
        code: grpc.status.UNAVAILABLE,
        message: 'Service is shutting down',
      });
      return;
    }

    if (!this.validateRequest(metadata)) {
      callback({
        code: grpc.status.UNAUTHENTICATED,
        message: 'Invalid authentication token',
      });
      return;
    }

    const connId = `conn-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
    this.pool.add(connId);

    // Process the request
    const response = { status: 'OK', timestamp: Date.now() };

    this.pool.remove(connId);
    callback(null, response);
  }

  public async start(): Promise<void> {
    const bindAddress = `0.0.0.0:${this.config.port}`;

    this.server.addService(
      { healthCheck: { path: '/health.HealthService/Check', requestStream: false, responseStream: false, requestSerialize: (v: any) => Buffer.from(JSON.stringify(v)), requestDeserialize: (v: Buffer) => JSON.parse(v.toString()), responseSerialize: (v: any) => Buffer.from(JSON.stringify(v)), responseDeserialize: (v: Buffer) => JSON.parse(v.toString()) } },
      { healthCheck: this.handleRequest.bind(this) }
    );

    return new Promise((resolve, reject) => {
      this.server.bindAsync(bindAddress, grpc.ServerCredentials.createInsecure(), (err) => {
        if (err) { reject(err); return; }
        this.server.start();
        console.log(`gRPC server listening on ${bindAddress}`);
        resolve();
      });
    });
  }
}

const service = new GrpcHealthService();
service.start().catch(console.error);

export { GrpcHealthService, ConnectionPool };
